CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text, avatar_url text, preferences jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own ON public.profiles FOR ALL TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name, avatar_url) VALUES (NEW.id, NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'avatar_url'); RETURN NEW; END; $$;
CREATE TRIGGER on_agency_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), name text NOT NULL, channel_url text, channel_thumbnail text, channel_summary text, offers text, content_strategy text, plan_type text CHECK (plan_type IN ('TEAM_ONLY','PERSONAL_INVOLVED','CUSTOM')), custom_plan_label text, setup_fee numeric NOT NULL DEFAULT 30000, monthly_fee numeric, start_date date, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','CHURNED')), discord_server_id text, google_account_email text, notes text);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.clients TO authenticated;
GRANT ALL ON public.clients TO service_role;
ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;
CREATE POLICY clients_own ON public.clients FOR ALL TO authenticated USING(owner_id = auth.uid()) WITH CHECK(owner_id = auth.uid());
CREATE TABLE public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE, amount numeric NOT NULL, type text NOT NULL CHECK(type IN ('SETUP','MONTHLY')), due_date date, paid_date date, status text CHECK(status IN ('PENDING','PAID','OVERDUE')));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.payments TO authenticated;
GRANT ALL ON public.payments TO service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_own ON public.payments FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid()));
CREATE TABLE public.team_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE, role text CHECK(role IN ('CHANNEL_MANAGER','SHORT_FORM_EDITOR','LONG_FORM_EDITOR','THUMBNAIL_DESIGNER')), name text NOT NULL, cost numeric);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.team_members TO authenticated;
GRANT ALL ON public.team_members TO service_role;
ALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_members_own ON public.team_members FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid()));
CREATE TABLE public.client_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE, stage text CHECK(stage IN ('WAITING_FOR_FOOTAGE','FILMING','EDITING_SHORT_FORM','EDITING_LONG_FORM','DESIGNING_THUMBNAIL','IN_REVIEW','UPLOADING','PUBLISHED')), source text CHECK(source IN ('MANUAL','AI_DISCORD')), notes text, updated_at timestamptz DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.client_progress TO authenticated;
GRANT ALL ON public.client_progress TO service_role;
ALTER TABLE public.client_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY progress_own ON public.client_progress FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid()));
CREATE TABLE public.analytics_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE, date date, views bigint, subscribers bigint, watch_hours numeric, impressions_ctr numeric, top_videos jsonb);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.analytics_snapshots TO authenticated;
GRANT ALL ON public.analytics_snapshots TO service_role;
ALTER TABLE public.analytics_snapshots ENABLE ROW LEVEL SECURITY;
CREATE POLICY snapshots_own ON public.analytics_snapshots FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid()));
CREATE TABLE public.ideation_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), title text NOT NULL, client_id uuid REFERENCES public.clients(id) ON DELETE CASCADE, created_at timestamptz DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ideation_threads TO authenticated;
GRANT ALL ON public.ideation_threads TO service_role;
ALTER TABLE public.ideation_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY threads_own ON public.ideation_threads FOR ALL TO authenticated USING(owner_id = auth.uid()) WITH CHECK(owner_id = auth.uid() AND (client_id IS NULL OR EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid())));
CREATE TABLE public.ideation_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.ideation_threads(id) ON DELETE CASCADE, role text CHECK(role IN ('user','assistant')), content text, timestamp timestamptz DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ideation_messages TO authenticated;
GRANT ALL ON public.ideation_messages TO service_role;
ALTER TABLE public.ideation_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_own ON public.ideation_messages FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.ideation_threads t WHERE t.id = thread_id AND t.owner_id = auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.ideation_threads t WHERE t.id = thread_id AND t.owner_id = auth.uid()));
CREATE TABLE public.thumbnail_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE, title text, created_at timestamptz DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.thumbnail_sessions TO authenticated;
GRANT ALL ON public.thumbnail_sessions TO service_role;
ALTER TABLE public.thumbnail_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY sessions_own ON public.thumbnail_sessions FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid()));
CREATE TABLE public.thumbnail_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.thumbnail_sessions(id) ON DELETE CASCADE, role text CHECK(role IN ('user','assistant')), content text, image_url text, rating integer CHECK(rating BETWEEN 1 AND 5), timestamp timestamptz DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.thumbnail_messages TO authenticated;
GRANT ALL ON public.thumbnail_messages TO service_role;
ALTER TABLE public.thumbnail_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY thumbnail_messages_own ON public.thumbnail_messages FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.thumbnail_sessions s JOIN public.clients c ON c.id = s.client_id WHERE s.id = session_id AND c.owner_id = auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.thumbnail_sessions s JOIN public.clients c ON c.id = s.client_id WHERE s.id = session_id AND c.owner_id = auth.uid()));
CREATE TABLE public.knowledge_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), scope text CHECK(scope IN ('THUMBNAIL_GLOBAL','VIDEO_GLOBAL','CLIENT_TITLES','CLIENT_IDEAS')), client_id uuid REFERENCES public.clients(id) ON DELETE CASCADE, user_input text, learned_principle text, timestamp timestamptz DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.knowledge_entries TO authenticated;
GRANT ALL ON public.knowledge_entries TO service_role;
ALTER TABLE public.knowledge_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY knowledge_own ON public.knowledge_entries FOR ALL TO authenticated USING(owner_id = auth.uid()) WITH CHECK(owner_id = auth.uid() AND (client_id IS NULL OR EXISTS(SELECT 1 FROM public.clients c WHERE c.id = client_id AND c.owner_id = auth.uid())));
CREATE TABLE public.leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), name text NOT NULL, channel_url text, notes text, status text CHECK(status IN ('TO_CONTACT','CONTACTED','IN_TALKS','CLOSED','LOST')), upfront_cash numeric, monthly_recurring numeric);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.leads TO authenticated;
GRANT ALL ON public.leads TO service_role;
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY leads_own ON public.leads FOR ALL TO authenticated USING(owner_id = auth.uid()) WITH CHECK(owner_id = auth.uid());
CREATE TABLE public.app_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), key text NOT NULL, value text, UNIQUE(owner_id,key));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.app_settings TO authenticated;
GRANT ALL ON public.app_settings TO service_role;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_own ON public.app_settings FOR ALL TO authenticated USING(owner_id = auth.uid()) WITH CHECK(owner_id = auth.uid());
COMMENT ON TABLE public.app_settings IS 'Non-secret configuration and integration status only. Private API keys belong in managed server secrets, never in this table.';
CREATE INDEX payments_client_idx ON public.payments(client_id);
CREATE INDEX team_client_idx ON public.team_members(client_id);
CREATE INDEX progress_client_idx ON public.client_progress(client_id);
CREATE INDEX snapshots_client_idx ON public.analytics_snapshots(client_id);
CREATE INDEX messages_thread_idx ON public.ideation_messages(thread_id);
CREATE INDEX thumbnail_messages_session_idx ON public.thumbnail_messages(session_id);